      if (typeof search !== 'string') return '';
      var query = search.charAt(0) === '?' ? search.slice(1) : search;
      // Split on '?' as well as '&': RevenueCat appends app_user_id to the
      // success URL, and a second '?' would otherwise swallow the plan.
